def blocks(g):
    rows=[r for r in g if all(x==0 for x in r)]
    rowgroups=[]; cur=[]
    for j in range(len(g)):
        if j in rows: 
            if cur: rowgroups.append(cur); cur=[]
        else: cur.append(j)
    if cur: rowgroups.append(cur)
    cols=[c for c in range(len(g[0])) if g[0][c]==0]
    colgroups=[]; cur=[]
    for c in range(len(g[0])):
        if c in cols: 
            if cur: colgroups.append(cur); cur=[]
        else: cur.append(c)
    if cur: colgroups.append(cur)
    return rowgroups,colgroups
